"""Private artifact storage: local filesystem (dev / single host) or S3-compatible object storage."""

from __future__ import annotations

import hashlib
import os
import re
import shutil
import tempfile
from collections.abc import Iterator
from contextlib import contextmanager
from functools import lru_cache
from pathlib import Path
from typing import BinaryIO, Protocol

from .config import Settings, get_settings

_KEY_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_\-./]{0,400}$")


class StorageError(Exception):
    pass


def validate_key(key: str) -> str:
    """Storage keys are generated by us, but validate anyway: no traversal, no absolute paths."""
    if not _KEY_RE.match(key) or ".." in key.split("/") or "//" in key or key.endswith("/"):
        raise StorageError(f"invalid storage key: {key!r}")
    return key


class Storage(Protocol):
    def put_file(self, key: str, src: Path, content_type: str) -> int: ...
    def open(self, key: str) -> BinaryIO: ...
    def exists(self, key: str) -> bool: ...
    def delete_prefix(self, prefix: str) -> None: ...
    def size(self, key: str) -> int: ...
    def total_bytes(self) -> int: ...
    def presigned_url(self, key: str, filename: str, ttl: int) -> str | None: ...
    @contextmanager
    def local_path(self, key: str) -> Iterator[Path]: ...


class LocalStorage:
    """Files live under a private root that is never served statically."""

    def __init__(self, root: Path):
        self.root = root.resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def _path(self, key: str) -> Path:
        validate_key(key)
        p = (self.root / key).resolve()
        if self.root != p and self.root not in p.parents:
            raise StorageError("path escapes storage root")
        return p

    def put_file(self, key: str, src: Path, content_type: str) -> int:
        dst = self._path(key)
        dst.parent.mkdir(parents=True, exist_ok=True)
        tmp = dst.with_name(dst.name + ".part")
        shutil.copyfile(src, tmp)
        os.replace(tmp, dst)
        return dst.stat().st_size

    def open(self, key: str) -> BinaryIO:
        return self._path(key).open("rb")

    def exists(self, key: str) -> bool:
        return self._path(key).is_file()

    def size(self, key: str) -> int:
        return self._path(key).stat().st_size

    def delete_prefix(self, prefix: str) -> None:
        p = self._path(prefix.rstrip("/"))
        if p.is_dir():
            shutil.rmtree(p, ignore_errors=True)
        elif p.is_file():
            p.unlink(missing_ok=True)

    def total_bytes(self) -> int:
        return sum(f.stat().st_size for f in self.root.rglob("*") if f.is_file())

    def presigned_url(self, key: str, filename: str, ttl: int) -> str | None:
        return None  # API issues HMAC-signed URLs for local storage

    @contextmanager
    def local_path(self, key: str) -> Iterator[Path]:
        yield self._path(key)

    def file_path(self, key: str) -> Path:
        return self._path(key)


class S3Storage:
    def __init__(self, settings: Settings):
        import boto3  # optional dependency

        if not settings.s3_bucket:
            raise StorageError("STEMFORGE_S3_BUCKET is required for s3 storage")
        self.bucket = settings.s3_bucket
        self.prefix = settings.s3_prefix
        self.client = boto3.client("s3", endpoint_url=settings.s3_endpoint_url, region_name=settings.s3_region)

    def _k(self, key: str) -> str:
        return self.prefix + validate_key(key)

    def put_file(self, key: str, src: Path, content_type: str) -> int:
        self.client.upload_file(
            str(src), self.bucket, self._k(key),
            ExtraArgs={"ContentType": content_type, "ServerSideEncryption": "AES256"},
        )
        return src.stat().st_size

    def open(self, key: str) -> BinaryIO:
        return self.client.get_object(Bucket=self.bucket, Key=self._k(key))["Body"]

    def exists(self, key: str) -> bool:
        try:
            self.client.head_object(Bucket=self.bucket, Key=self._k(key))
            return True
        except Exception:
            return False

    def size(self, key: str) -> int:
        return int(self.client.head_object(Bucket=self.bucket, Key=self._k(key))["ContentLength"])

    def delete_prefix(self, prefix: str) -> None:
        paginator = self.client.get_paginator("list_objects_v2")
        for page in paginator.paginate(Bucket=self.bucket, Prefix=self._k(prefix.rstrip("/")) + "/"):
            objs = [{"Key": o["Key"]} for o in page.get("Contents", [])]
            if objs:
                self.client.delete_objects(Bucket=self.bucket, Delete={"Objects": objs})

    def total_bytes(self) -> int:
        total = 0
        paginator = self.client.get_paginator("list_objects_v2")
        for page in paginator.paginate(Bucket=self.bucket, Prefix=self.prefix):
            total += sum(o["Size"] for o in page.get("Contents", []))
        return total

    def presigned_url(self, key: str, filename: str, ttl: int) -> str | None:
        return self.client.generate_presigned_url(
            "get_object",
            Params={
                "Bucket": self.bucket, "Key": self._k(key),
                "ResponseContentDisposition": f'attachment; filename="{filename}"',
            },
            ExpiresIn=ttl,
        )

    @contextmanager
    def local_path(self, key: str) -> Iterator[Path]:
        fd, name = tempfile.mkstemp(suffix=Path(key).suffix)
        os.close(fd)
        try:
            self.client.download_file(self.bucket, self._k(key), name)
            yield Path(name)
        finally:
            Path(name).unlink(missing_ok=True)


@lru_cache
def get_storage() -> Storage:
    settings = get_settings()
    if settings.storage_backend == "s3":
        return S3Storage(settings)
    return LocalStorage(settings.storage_dir)


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()
